commits.patch:
diff --git a/src/media_tools/crypt_tools.c b/src/media_tools/crypt_tools.c
index 83c6dc9..c25b738 100644
--- a/src/media_tools/crypt_tools.c
+++ b/src/media_tools/crypt_tools.c
@@ -285,15 +285,22 @@ static char *crypt_cpix_hls_info(char *b64)
 	GF_Err e;
 	u8 *data = NULL;
 	u32 size = 0;
-	char *text = b64, *sep, *end;
+	char *text, *sep, *end;
 	e = crypt_cpix_decode_b64(b64, &data, &size);
-	if (e) {
-		gf_free(b64);
+	if (e) return NULL;
+	text = (char *) gf_malloc(size+1);
+	if (!text) {
+		gf_free(data);
 		return NULL;
 	}
 	memcpy(text, data, size);
 	text[size] = 0;
 	gf_free(data);
+	if (strstr(text, "URI=") && !strstr(text, "URI=\"")) {
+		memcpy(b64, text, size+1);
+		gf_free(text);
+		text = b64;
+	}
 	sep = strchr(text, ':');
 	if (sep && ((strstr(text, "#EXT-X-KEY:") == text) || (strstr(text, "#EXT-X-SESSION-KEY:") == text))) {
 		sep = strchr(sep+1, ',');
@@ -306,7 +313,7 @@ static char *crypt_cpix_hls_info(char *b64)
 	while ((end > text) && isspace(end[-1])) end--;
 	*end = 0;
 	if (!strstr(text, "URI=\"")) {
-		gf_free(text);
+		if (text != b64) gf_free(text);
 		return NULL;
 	}
 	return text;
@@ -579,6 +586,7 @@ static GF_Err cryptinfo_load_cpix(const char *file, GF_CryptInfo **out_info)
 					continue;

 				hls = crypt_cpix_hls_info(text);
+				gf_free(text);
 				text = NULL;
 				if (!hls)
 					continue;

diff --git a/src/media_tools/crypt_tools.c b/src/media_tools/crypt_tools.c
--- a/src/media_tools/crypt_tools.c
+++ b/src/media_tools/crypt_tools.c
@@ -290,7 +290,7 @@
 	end = text + strlen(text);
 	while ((end > text) && isspace(end[-1])) end--;
 	*end = 0;
-	if (!strstr(text, "URI=\"")) {
+	if (!strstr(text, "URI=")) {
 		gf_free(text);
 		return NULL;
 	}
